def simplifyPath(self, path: str) -> str:
    stack: list[str] = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue                        # redundant slash or current dir
        elif part == '..':
            if stack:
                stack.pop()                 # go up, but never above root
        else:
            stack.append(part)              # real directory name
    return '/' + '/'.join(stack)

